public class Main {
    public static void main(String[] args) {
        ArrayList<String> operator = new ArrayList<>(Arrays.asList("+", "*", "-"));
        ArrayList<Integer> operand = new ArrayList<>(Arrays.asList(2, 3, 4, 5));
        System.out.println(doAlgebra(operator, operand));
    }

    public static int doAlgebra(ArrayList<String> operator, ArrayList<Integer> operand) {
        StringBuilder expression = new StringBuilder(Integer.toString(operand.get(0)));
        for (int i = 0; i < operator.size(); i++) {
            expression.append(operator.get(i));
            expression.append(operand.get(i + 1));
        }
        return evalExpression(expression.toString());
    }

    public static int evalExpression(String expression) {
        return new Expression(expression).evaluate();
    }

    static class Expression {
        private String expression;

        Expression(String expression) {
            this.expression = expression;
        }

        int evaluate() {
            return new ExpressionParser(this.expression).parse().evaluate();
        }
    }

    static class ExpressionParser {
        private String expression;
        private int pos = 0;

        ExpressionParser(String expression) {
            this.expression = expression;
        }

        ExpressionNode parse() {
            ExpressionNode node = parseSum();
            if (pos < expression.length()) {
                throw new IllegalArgumentException("Unexpected char: " + expression.charAt(pos));
            }
            return node;
        }

        private ExpressionNode parseSum() {
            ExpressionNode node = parseProduct();
            while (pos < expression.length()) {
                char op = expression.charAt(pos);
                if (op != '+' && op != '-') {
                    return node;
                }
                pos++;
                node = new BinaryExpressionNode(node, parseProduct(), op);
            }
            return node;
        }

        private ExpressionNode parseProduct() {
            ExpressionNode node = parsePower();
            while (pos < expression.length()) {
                char op = expression.charAt(pos);
                if (op != '*' && op != '/') {
                    return node;
                }
                pos++;
                node = new BinaryExpressionNode(node, parsePower(), op);
            }
            return node;
        }

        private ExpressionNode parsePower() {
            ExpressionNode node = parseAtom();
            while (pos < expression.length()) {
                char op = expression.charAt(pos);
                if (op != '^') {
                    return node;
                }
                pos++;
                node = new BinaryExpressionNode(node, parseAtom(), op);
            }
            return node;
        }

        private ExpressionNode parseAtom() {
            if (expression.charAt(pos) == '(') {
                pos++;
                ExpressionNode node = parseSum();
                if (expression.charAt(pos) != ')') {
                    throw new IllegalArgumentException("Expected ')'");
                }
                pos++;
                return node;
            }
            return parseNumber();
        }

        private ExpressionNode parseNumber() {
            int start = pos;
            while (pos < expression.length() && Character.isDigit(expression.charAt(pos))) {
                pos++;
            }
            return new NumberNode(Integer.parseInt(expression.substring(start, pos)));
        }
    }

    interface ExpressionNode {
        int evaluate();
    }

    static class NumberNode implements ExpressionNode {
        private int value;

        NumberNode(int value) {
            this.value = value;
        }

        public int evaluate() {
            return value;
        }
    }

    static class BinaryExpressionNode implements ExpressionNode {
        private ExpressionNode left, right;
        private char op;

        BinaryExpressionNode(ExpressionNode left, ExpressionNode right, char op) {
